def build_planning_graph(checkpointer: AsyncSqliteSaver | None):
    """
    Builds and compiles the planning StateGraph.

    Args:
        checkpointer: AsyncSqliteSaver instance â€” caller manages its lifecycle
                      (must be used as an async context manager before passing in).

    Returns:
        Compiled CompiledGraph ready for ainvoke / astream.
    """
    graph = StateGraph(PlanningState)

    # â”€â”€ Register nodes â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    graph.add_node("load_requirements",  load_requirements_node)
    graph.add_node("pattern_selector",   pattern_selector_node)
    graph.add_node("complexity_router",  complexity_router_node)
    graph.add_node("researcher",         researcher_node)
    graph.add_node("architect",          architect_node)
    graph.add_node("planner",            planner_node)
    graph.add_node("critic",             critic_node)
    graph.add_node("approval_gate",      approval_gate_node)
    graph.add_node("save_result",        save_result_node)

    # â”€â”€ Linear edges (deterministic) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    graph.add_edge(START,                "load_requirements")
    graph.add_edge("load_requirements",  "pattern_selector")
    graph.add_edge("pattern_selector",   "complexity_router")

    # After researcher, always go to architect
    graph.add_edge("researcher",         "architect")

    # After architect, always plan
    graph.add_edge("architect",          "planner")

    # After planner, always critique
    graph.add_edge("planner",            "critic")

    # save_result is terminal
    graph.add_edge("save_result",        END)

    # â”€â”€ Conditional edges â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

    # complexity_router â†’ researcher (complex) | architect (simple)
    graph.add_conditional_edges(
        "complexity_router",
        route_complexity,
        {
            "researcher": "researcher",
            "architect":  "architect",
        },
    )

    # critic â†’ planner (retry) | approval_gate (pass or max iterations)
    graph.add_conditional_edges(
        "critic",
        route_critic,
        {
            "planner":       "planner",
            "approval_gate": "approval_gate",
        },
    )

    # approval_gate â†’ save_result (approve) | planner (reject + revise)
    graph.add_conditional_edges(
        "approval_gate",
        route_approval,
        {
            "save_result": "save_result",
            "planner":     "planner",
        },
    )

    logger.info("planning_graph compiled â€” nodes: %s",
                list(graph.nodes.keys()))

    return graph.compile(checkpointer=checkpointer)


@asynccontextmanager
async def get_planning_graph():
    """
    Async context-managed factory.
    Usage (in service or router):

        async with get_planning_graph() as planning_graph:
            await planning_graph.ainvoke(initial_state, config={"configurable": {"thread_id": run_id}})
    """
    checkpoint_dir = os.path.dirname(os.path.abspath(settings.CHECKPOINT_DB_PATH))
    os.makedirs(checkpoint_dir, exist_ok=True)

    async with AsyncSqliteSaver.from_conn_string(
        settings.CHECKPOINT_DB_PATH
    ) as checkpointer:
        yield build_planning_graph(checkpointer)


def get_graph_png_bytes() -> bytes:
    graph = build_planning_graph(checkpointer=None)
    try:
        return graph.get_graph().draw_mermaid_png()
    except Exception as exc:
        logger.warning("planning_graph_png_fallback", extra={"error": str(exc)})
        return render_workflow_graph_png(
            "Workflow 2: Planning",
            [
                "Load approved requirements package",
                "Select reusable implementation patterns",
                "Route simple plans directly or complex plans through research",
                "Generate architecture and task plan",
                "Critique plan and loop until accepted or iteration cap is reached",
                "Pause at approval gate and resume from human decision",
                "Save approved planning artifacts",
            ],
        )
